// Слоты режима ребёнка (решение пользователя 08.11, #8ca267).
// С #8ca267 режим ребёнка хранится на СЕРВЕРЕ по сессии входа: после «<имя>, בואו נתחיל!» файл входа
// .qa/auth/<slot>.json остаётся в режиме ребёнка, пока не введены пароль/PIN (автотесты их не вводят).
// Поэтому: один слот = один ребёнок, слот постоянно в режиме этого ребёнка. Основные parent.json / parent-b.json
// в режим ребёнка НЕ переводятся никогда. Удаление benjico\child-context из выхода больше не выводит — не используется.
// Слоты выдаёт пользователь вручную: npm run qa-login:manual -- <slot>. Пароль и PIN здесь не вводятся.
// Тесты на одном слоте не должны идти параллельно → пометка @data (проект data, по одному) или serial.
import { Browser, BrowserContext, BrowserContextOptions, Page, TestInfo, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

export interface ChildSlot {
  /** id файла входа: .qa/auth/<slot>.json */
  slot: string;
  /** Аккаунт, под которым выдан слот (для подсказки при ошибке) */
  account: string;
  childId: string;
  nickname: string;
}

/** Слоты: один слот — один ребёнок. Новые слоты добавлять сюда и в accounts.json. */
export const CHILD_SLOTS = {
  /** QA-R2-V (ארנבת), семья parent, PIN не задан → гейт «אימות זהות». */
  'QA-R2-V': { slot: 'parent-auto', account: 'parent', childId: '26592b73-eaa6-439f-ab3f-d98a0bd1871b', nickname: 'QA-R2-V' },
  /** QA-R2-1 (рекомендации, #37cdff), семья parent. Слот выдаёт пользователь: npm run qa-login:manual -- parent-r21-auto */
  'QA-R2-1': { slot: 'parent-r21-auto', account: 'parent', childId: 'b9ef1552-4cc7-4d72-a9c3-d02d66d19af1', nickname: 'QA-R2-1' },
} as const satisfies Record<string, ChildSlot>;

export const slotFile = (slot: string) => path.resolve(__dirname, '../../auth', `${slot}.json`);

function requireSlotFile(slot: string): string {
  const file = slotFile(slot);
  if (!fs.existsSync(file)) {
    throw new Error(`Нет слота «${slot}» (.qa/auth/${slot}.json). Слот выдаёт пользователь: npm run qa-login:manual -- ${slot}`);
  }
  return file;
}

/** storageState слота для test.use({ storageState: slotState(...) }). */
export const slotState = (child: ChildSlot) => slotFile(child.slot);

/**
 * Отдельное окно со слотом (для сценариев с несколькими ролями / beforeAll).
 * Параметры окна — из текущего проекта, как в fixtures.ts. В конце обязательно saveSlot(...) и context.close().
 */
export async function openSlotPage(browser: Browser, testInfo: TestInfo, child: ChildSlot): Promise<{ context: BrowserContext; page: Page }> {
  const storageState = requireSlotFile(child.slot);
  const keys = ['baseURL', 'locale', 'viewport', 'userAgent', 'deviceScaleFactor', 'isMobile', 'hasTouch', 'timezoneId'] as const;
  const projectUse = testInfo.project.use as Record<string, unknown>;
  const options: BrowserContextOptions = {};
  for (const k of keys) if (projectUse[k] !== undefined) (options as Record<string, unknown>)[k] = projectUse[k];
  const context = await browser.newContext({ ...options, storageState });
  return { context, page: await context.newPage() };
}

/**
 * Сохранить сессию слота обратно в файл: refresh-токен Supabase одноразовый, без сохранения следующий прогон
 * получит уже использованный токен. Вызывать в конце теста (afterEach / afterAll / finally), пока окно открыто.
 */
export async function saveSlot(context: BrowserContext | undefined, child: ChildSlot) {
  if (!context) return;
  try {
    await context.storageState({ path: slotFile(child.slot) });
  } catch {
    /* окно уже закрыто — сохранять нечего */
  }
}

const visible = (page: Page, text: string | RegExp) => page.getByText(text, { exact: typeof text === 'string' }).filter({ visible: true }).first();

/** Видимый гейт выхода из режима ребёнка: «אימות זהות» (пароль, семья без PIN) или клавиатура B3 (PIN). */
export function parentGate(page: Page) {
  return visible(page, 'אימות זהות').or(visible(page, 'הזינו את קוד ההורים בן 4 הספרות')).first();
}

/** Закрыть гейт без ввода: «ביטול» (окно пароля) или «חזרה לתרגול» (клавиатура PIN). Цифры и пароль не трогаем. */
export async function dismissGate(page: Page) {
  const cancel = page.getByRole('button', { name: 'ביטול', exact: true }).filter({ visible: true }).first();
  const back = page.getByRole('button', { name: 'חזרה לתרגול' }).or(page.getByRole('link', { name: 'חזרה לתרגול' })).filter({ visible: true }).first();
  if (await cancel.isVisible()) await cancel.click();
  else if (await back.isVisible()) await back.click();
  await expect(parentGate(page), 'гейт закрыт').toBeHidden();
}

/**
 * Привести слот на дом ребёнка /<childId>/home — в обоих случаях:
 * - слот ещё не в режиме ребёнка (первый прогон после выдачи) → экран передачи → «<имя>, בואו נתחיל!» (→ «אחר כך», если intro);
 * - слот уже в режиме ребёнка → сервер возвращает в дом ребёнка (+ гейт) → закрыть гейт без ввода.
 * Если открылся дом ДРУГОГО ребёнка или экран входа — слот испорчен: понятная ошибка «выдать заново».
 */
export async function goChildHome(page: Page, child: ChildSlot) {
  const start = page.getByRole('button', { name: `${child.nickname}, בואו נתחיל!` }).filter({ visible: true }).first();
  const later = page.getByRole('button', { name: 'אחר כך', exact: true }).filter({ visible: true }).first();
  const homeTab = page.getByRole('tab', { name: 'בית' }).filter({ visible: true }).first();
  const signIn = page.getByRole('button', { name: 'כניסה', exact: true }).filter({ visible: true }).first();
  const homeRe = new RegExp(`/${child.childId}/home(?:[?#]|$)`);

  await page.goto(`/children/${child.childId}/handover`);
  await expect(start.or(later).or(homeTab).or(parentGate(page)).or(signIn).first()).toBeVisible({ timeout: 30_000 });

  const p = new URL(page.url()).pathname;
  if ((await signIn.isVisible()) || p.startsWith('/sign-in')) {
    throw new Error(`Слот «${child.slot}» вышел из аккаунта — выдать заново: npm run qa-login:manual -- ${child.slot}`);
  }
  const otherChild = p.match(/^\/([0-9a-f-]{36})\//);
  if (otherChild && otherChild[1] !== child.childId) {
    throw new Error(`Слот «${child.slot}» в режиме другого ребёнка (${otherChild[1]}), а нужен ${child.nickname} — выдать заново: npm run qa-login:manual -- ${child.slot}`);
  }

  if (await start.isVisible()) {
    // Слот ещё не в режиме ребёнка — передача (с этого момента слот навсегда в режиме этого ребёнка)
    await start.click();
    await expect(later.or(homeTab).first()).toBeVisible({ timeout: 30_000 });
  }
  if (await parentGate(page).isVisible()) await dismissGate(page);
  if (await later.isVisible()) await later.click();
  await page.waitForURL(homeRe);
  if (await parentGate(page).isVisible()) await dismissGate(page);
  await expect(homeTab).toBeVisible();
}
